            sh:resultPath prov:qualifiedCommunication ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/prov/#prop-qualifiedCommunication> ;
            sh:value [ prov:activity <file:///github/workspace/activity-source-validation-run> ;
                    prov:atTime "2024-05-01T09:30:00+00:00"^^xsd:dateTime ] ],
        [ a sh:ValidationResult ;
