            sh:resultMessage "Node [ prov:activity <file:///github/workspace/activity-source-observation-run> ; prov:atTime Literal(\"2024-05-01T08:00:00+00:00\" = 2024-05-01 08:00:00+00:00, datatype=xsd:dateTime) ] does not conform to one or more shapes in [ sh:nodeKind sh:BlankNode ; sh:or ( [ sh:class prov:Communication ] ) ] , [ sh:nodeKind sh:IRI ]" ;
            sh:resultPath prov:qualifiedCommunication ;
